import math

def get_primes(limit):
    primes = []
    is_prime = [True] * (limit + 1)
    is_prime[0] = is_prime[1] = False
    for p in range(2, limit + 1):
        if is_prime[p]:
            primes.append(p)
            for multiple in range(p * p, limit + 1, p):
                is_prime[multiple] = False
    return primes

def order(a, n):
    # Calculates the multiplicative order of a modulo n.
    # Assumes gcd(a, n) = 1.
    if n == 1:
        return 1

    phi_n = n - 1 if n > 1 and n.is_prime() else None # Euler's totient function (only needed if n is prime for simplicity here)

    # Since we are only testing p (prime), phi(p) = p-1.
    if n > 1 and n.is_prime():
        phi = n - 1
    else:
        # This case should not happen based on the task description (m=p prime)
        raise ValueError("n must be prime for this simplification.")

    factors = set()
    d = phi
    i = 2
    while i * i <= d:
        if d % i == 0:
            factors.add(i)
            while d % i == 0:
                d //= i
        i += 1
    if d > 1:
        factors.add(d)

    order_val = phi
    for f in factors:
        while order_val % f == 0 and pow(a, order_val // f, n) == 1:
            order_val //= f
    return order_val

def v2(n):
    # Calculates the exponent of the highest power of 2 dividing n (nu_2(n)).
    if n == 0:
        return float('inf')
    count = 0
    while n > 0 and n % 2 == 0:
        count += 1
        n //= 2
    return count

