import math
from functools import reduce

def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def phi(n):
    """Computes Euler's totient function phi(n)."""
    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1
    if n > 1:
        result -= result // n
    return result

def multiplicative_order(a, n):
    """Computes the multiplicative order of a modulo n, assuming gcd(a, n) = 1."""
    if gcd(a, n) != 1:
        return None # Should not happen given constraints

    phi_n = phi(n)

    # Find all divisors of phi_n
    divisors = set()
    for i in range(1, int(math.sqrt(phi_n)) + 1):
        if phi_n % i == 0:
            divisors.add(i)
            divisors.add(phi_n // i)

    sorted_divisors = sorted(list(divisors))

    # Check powers a^k mod n for each divisor k
    for k in sorted_divisors:
        if pow(a, k, n) == 1:
            return k

    # Should theoretically never be reached if phi(n) is correct
    return phi_n

def N_c(m):
    """
    Computes the number of disjoint cycles N_c(m) for the permutation x -> 3x mod m.
    m must not be divisible by 3.
    """
    if m <= 1 or m % 3 == 0:
        return 0 # Invalid input for this problem scope

    # Find all divisors d of m, where d < m.
    divisors = []
    for d in range(1, int(math.sqrt(m)) + 1):
        if m % d == 0:
            divisors.append(d)
            if d * d != m:
                divisors.append(m // d)

    total_cycles = 0

    # Sum over d|m, d < m
    for d in divisors:
        if d == m:
            continue

        n = m // d

        # We need ord_n(3). Since 3 does not divide m, it does not divide n.
        k = multiplicative_order(3, n)

        if k is None:
            # This should not happen if m % 3 != 0, but as a safeguard
            raise ValueError(f"GCD(3, {n}) is not 1 for m={m}, d={d}")

        # Contribution of elements x where gcd(x, m) = d
        # Number of such elements is phi(n)
        # Number of cycles = phi(n) / k
        contribution = phi(n) // k
        total_cycles += contribution

    return total_cycles

